#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testPrecisionFromString();

void testPrecisionFromString()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    // Test 1: Scientific notation negative exponent
    assertTrue(isEqual(exchange.precisionFromString(std::string("1e-4")), 4));
    // Test 2: Scientific notation uppercase E
    assertTrue(isEqual(exchange.precisionFromString(std::string("1E-4")), 4));
    // Test 3: Scientific notation larger negative exponent
    assertTrue(isEqual(exchange.precisionFromString(std::string("1e-8")), 8));
    // Test 4: Scientific notation with decimal
    assertTrue(isEqual(exchange.precisionFromString(std::string("2.5e-6")), 6));
    // Test 5: Scientific notation positive exponent
    assertTrue(isEqual(exchange.precisionFromString(std::string("1e4")), -4));
    // Test 6: Scientific notation explicit positive
    assertTrue(isEqual(exchange.precisionFromString(std::string("1e+4")), -4));
    // Test 7: Decimal string 4 places
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.0001")), 4));
    // Test 8: Decimal string 5 places
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.00001")), 5));
    // Test 9: Decimal string 1 place
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.1")), 1));
    // Test 10: Decimal string 2 places
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.01")), 2));
    // Test 11: Decimal string 8 places
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.00000001")), 8));
    // Test 12: Trailing zeros should be stripped
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.0100")), 2));
    // Test 13: Trailing zeros stripped
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.00100")), 3));
    // Test 14: All trailing zeros after decimal
    assertTrue(isEqual(exchange.precisionFromString(std::string("1.0000")), 0));
    // Test 15: Integer string (no decimal)
    assertTrue(isEqual(exchange.precisionFromString(std::string("1")), 0));
    // Test 16: Integer string larger
    assertTrue(isEqual(exchange.precisionFromString(std::string("10")), 0));
    // Test 17: Integer string even larger
    assertTrue(isEqual(exchange.precisionFromString(std::string("100")), 0));
    // Test 18: Zero with decimal
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.0")), 0));
    // Test 19: One with decimal
    assertTrue(isEqual(exchange.precisionFromString(std::string("1.0")), 0));
    // Test 20: Mixed precision
    assertTrue(isEqual(exchange.precisionFromString(std::string("0.12345")), 5));
}

